// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.intent.compoundimport com.roshan.persona.brain.intent.CompoundExecutorimport com.roshan.persona.brain.intent.Intentimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Stage 5: Compound Intent Detector. * * Detects multiple intents in one utterance. * * Splits input on connectors {"and", "then", "after that", "also"}. * Each sub-utterance goes through Stages 1-3 independently. * Results merged into [Intent.Compound]. * * Examples: *   "torch on and call mom" → Compound([TorchOn, Call("mom")], SEQUENTIAL) *   "mute and dim screen" → Compound([Mute, SetBrightness], PARALLEL) *   "if battery < 20% then saver" → Compound([CheckBattery, EnableSaver], CONDITIONAL) * * @see <a href="docs/spec/module2-spec-review.pdf">§4.5 CompoundIntent</a> */@Singletonclass CompoundIntentDetector @Inject constructor() {    /** Connectors that split compound intents. */    private val sequentialConnectors = setOf("then", "after that", "next", "afterwards")    private val parallelConnectors = setOf("and", "also", "as well as", "while")    private val conditionalConnectors = setOf("if", "when", "in case", "assuming")    /**     * Detect compound intent in [input].     *     * @param classifySubUtterance function that classifies a sub-utterance     *        (provided by IntentClassifier — reuses Stage 1-3 pipeline).     * @return [Intent.Compound] if compound detected, null otherwise.     */    suspend fun detect(        input: String,        classifySubUtterance: suspend (String) -> Intent?,    ): Intent.Compound? {        val split = splitOnConnectors(input)        if (split.subUtterances.size < 2) return null        val intents = mutableListOf<Intent>()        for (sub in split.subUtterances) {            val intent = classifySubUtterance(sub) ?: return null  // if any fails, not compound            intents.add(intent)        }        return Intent.Compound(            intents = intents,            executor = split.executor,        )    }    /** Split input on connectors. Returns split result with detected executor. */    private fun splitOnConnectors(input: String): SplitResult {        // Check for conditional first (highest priority)        // Conditional connectors often appear at the start ("if X then Y")        for (connector in conditionalConnectors) {            // Conditional split: connector can be at start or middle            val startsWithConnector = Regex("(?i)^\\s*${Regex.escape(connector)}\\b").containsMatchIn(input)            if (startsWithConnector) {                // Strip the leading conditional connector, then split remaining on "then"                val stripped = Regex("(?i)^\\s*${Regex.escape(connector)}\\b").replace(input, "").trim()                // Look for "then" to split condition from action                val thenSplit = stripped.split(Regex("(?i)\\bthen\\b")).map { it.trim() }.filter { it.isNotBlank() }                if (thenSplit.size >= 2) {                    return SplitResult(thenSplit, CompoundExecutor.CONDITIONAL)                }                // No "then" — treat whole stripped as condition, no action yet                if (stripped.isNotBlank()) {                    return SplitResult(listOf(stripped, ""), CompoundExecutor.CONDITIONAL)                }            } else {                // Connector in middle — split normally                val parts = splitOnConnector(input, connector)                if (parts.size >= 2) {                    return SplitResult(parts, CompoundExecutor.CONDITIONAL)                }            }        }        // Then sequential        for (connector in sequentialConnectors) {            val parts = splitOnConnector(input, connector)            if (parts.size >= 2) {                return SplitResult(parts, CompoundExecutor.SEQUENTIAL)            }        }        // Then parallel        for (connector in parallelConnectors) {            val parts = splitOnConnector(input, connector)            if (parts.size >= 2) {                return SplitResult(parts, CompoundExecutor.PARALLEL)            }        }        return SplitResult(listOf(input), CompoundExecutor.SEQUENTIAL)    }    /** Split input on a single connector phrase (case-insensitive, word-boundary). */    private fun splitOnConnector(input: String, connector: String): List<String> {        val pattern = Regex("(?i)\\b${Regex.escape(connector)}\\b")        val parts = input.split(pattern).map { it.trim() }.filter { it.isNotBlank() }        return parts    }    /** Result of splitting. */    private data class SplitResult(        val subUtterances: List<String>,        val executor: CompoundExecutor,    )}